const maxColNum = Math.max(
  ...sheetDetails.flatMap((item) => item.cellInfo.map((cell) => cell.colNum))
);
const maxRowNum = Math.max(
  ...sheetDetails.flatMap((item) => item.cellInfo.map((cell) => cell.rowNum))
);

const renderGrid = (sheetDetails) => {
  // Initialize a 2D array to track occupied spaces
  const occupiedGrid = Array.from({ length: maxRowNum }, () =>
    Array(maxColNum).fill(false)
  );

  // Mark occupied cells in the grid
  sheetDetails.forEach((form) => {
    form.cellInfo.forEach((cell) => {
      // Mark cells as occupied based on their rowNum and colNum
      for (let i = 0; i < cell.rowSpan; i++) {
        for (let j = 0; j < cell.colSpan; j++) {
          const rowIndex = cell.rowNum - 1 + i;
          const colIndex = cell.colNum - 1 + j;

          // Check if the indices are within bounds
          if (rowIndex < maxRowNum && colIndex < maxColNum) {
            occupiedGrid[rowIndex][colIndex] = true;
          }
        }
      }
    });
  });

  return (
    <Box
      sx={{
        display: "grid",
        gridTemplateColumns: `repeat(${maxColNum}, 1fr)`, // Create enough columns based on maxColNum
        gap: 0.2,
        padding: "1px",
      }}
    >
      {/* Render the grid cells with content */}
      {sheetDetails.map((form, formIndex) =>
        form.cellInfo.map((cell, cellIndex) => {
          // const parsedStyles = parseCssString(cell.cellCSS); // Assuming this function parses the CSS

          // const isPasted = pastedCells.has(cell.cellId); // Example of condition for styling
          // const isClicked = clickedCells.has(cell.cellId); // Example of condition for styling

          return (
            <Paper
              key={`${formIndex}-${cellIndex}`}
              elevation={3}
              sx={{
                gridColumn: `span ${cell.colSpan}`, // Handle column span
                gridRow: `span ${cell.rowSpan}`, // Handle row span
                padding: "20px",
                textAlign: "center",
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                position: "relative",
                //   ...parsedStyles,
                //   ...(isPasted ? { backgroundColor: "#c8e6c9" } : {}),
                gridColumnStart: cell.colNum, // Set the starting position for the column
                gridRowStart: cell.rowNum, // Set the starting position for the row
              }}
            >
              {`${cell.aliasId}(${cell.cellId})`}
            </Paper>
          );
        })
      )}

      {/* Render the empty Paper components for unoccupied spaces */}
      {occupiedGrid.map((row, rowIndex) =>
        row.map((isOccupied, colIndex) => {
          if (!isOccupied) {
            return (
              <Paper
                key={`empty-${rowIndex}-${colIndex}`}
                elevation={0} // No shadow for empty cells
                sx={{
                  gridColumnStart: colIndex + 1,
                  gridRowStart: rowIndex + 1,
                  padding: "20px",
                  textAlign: "center",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  position: "relative",
                  backgroundColor: "red", // Light background for empty cells
                }}
              />
            );
          }
          return null; // Return null for occupied spaces
        })
      )}
    </Box>
  );
};
export default function GridPlayGround() {
  return (
    <>
      <center>
        <div>{renderGrid(sheetDetails)}</div>
      </center>
    </>
  );
}
